import Database from 'better-sqlite3';
import { existsSync, mkdirSync } from 'fs';
import { dirname, join } from 'path';
import { homedir } from 'os';
import type { Person, Relationship, FamilyMember, SpouseInfo } from './types.js';

const DEFAULT_DATA_DIR = join(homedir(), '.vamsa');
const DEFAULT_DB_PATH = join(DEFAULT_DATA_DIR, 'family.db');

let db: Database.Database | null = null;
let currentDbPath: string = DEFAULT_DB_PATH;

export function getDataDir(): string {
  return dirname(currentDbPath);
}

export function getDbPath(): string {
  return currentDbPath;
}

export function initDatabase(dbPath: string = DEFAULT_DB_PATH): Database.Database {
  currentDbPath = dbPath;
  const dataDir = dirname(dbPath);

  if (!existsSync(dataDir)) {
    mkdirSync(dataDir, { recursive: true });
  }

  db = new Database(dbPath);
  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');

  // Create tables
  db.exec(`
    CREATE TABLE IF NOT EXISTS persons (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      birthday TEXT,
      birthplace TEXT,
      deathday TEXT,
      deathplace TEXT,
      notes TEXT,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP,
      updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    );

    CREATE TABLE IF NOT EXISTS relationships (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      person_id INTEGER NOT NULL,
      related_person_id INTEGER NOT NULL,
      relationship_type TEXT NOT NULL CHECK (relationship_type IN ('parent', 'spouse')),
      anniversary TEXT,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (person_id) REFERENCES persons(id) ON DELETE CASCADE,
      FOREIGN KEY (related_person_id) REFERENCES persons(id) ON DELETE CASCADE,
      UNIQUE(person_id, related_person_id, relationship_type)
    );

    CREATE INDEX IF NOT EXISTS idx_relationships_person ON relationships(person_id);
    CREATE INDEX IF NOT EXISTS idx_relationships_related ON relationships(related_person_id);
  `);

  return db;
}

export function getDatabase(): Database.Database {
  if (!db) {
    return initDatabase();
  }
  return db;
}

export function closeDatabase(): void {
  if (db) {
    db.close();
    db = null;
  }
}

// Person CRUD operations
export function addPerson(
  name: string,
  options: {
    birthday?: string;
    birthplace?: string;
    deathday?: string;
    deathplace?: string;
    notes?: string;
  } = {}
): Person {
  const database = getDatabase();
  const stmt = database.prepare(`
    INSERT INTO persons (name, birthday, birthplace, deathday, deathplace, notes)
    VALUES (?, ?, ?, ?, ?, ?)
  `);

  const result = stmt.run(
    name,
    options.birthday || null,
    options.birthplace || null,
    options.deathday || null,
    options.deathplace || null,
    options.notes || null
  );

  return getPerson(result.lastInsertRowid as number)!;
}

export function getPerson(id: number): Person | undefined {
  const database = getDatabase();
  const stmt = database.prepare('SELECT * FROM persons WHERE id = ?');
  return stmt.get(id) as Person | undefined;
}

export function getAllPersons(): Person[] {
  const database = getDatabase();
  const stmt = database.prepare('SELECT * FROM persons ORDER BY name');
  return stmt.all() as Person[];
}

export function updatePerson(
  id: number,
  updates: {
    name?: string;
    birthday?: string | null;
    birthplace?: string | null;
    deathday?: string | null;
    deathplace?: string | null;
    notes?: string | null;
  }
): Person | undefined {
  const database = getDatabase();
  const person = getPerson(id);
  if (!person) return undefined;

  const fields: string[] = [];
  const values: (string | null)[] = [];

  if (updates.name !== undefined) {
    fields.push('name = ?');
    values.push(updates.name);
  }
  if (updates.birthday !== undefined) {
    fields.push('birthday = ?');
    values.push(updates.birthday);
  }
  if (updates.birthplace !== undefined) {
    fields.push('birthplace = ?');
    values.push(updates.birthplace);
  }
  if (updates.deathday !== undefined) {
    fields.push('deathday = ?');
    values.push(updates.deathday);
  }
  if (updates.deathplace !== undefined) {
    fields.push('deathplace = ?');
    values.push(updates.deathplace);
  }
  if (updates.notes !== undefined) {
    fields.push('notes = ?');
    values.push(updates.notes);
  }

  if (fields.length === 0) return person;

  fields.push('updated_at = CURRENT_TIMESTAMP');
  values.push(id.toString());

  const stmt = database.prepare(`UPDATE persons SET ${fields.join(', ')} WHERE id = ?`);
  stmt.run(...values);

  return getPerson(id);
}

export function deletePerson(id: number): boolean {
  const database = getDatabase();
  const stmt = database.prepare('DELETE FROM persons WHERE id = ?');
  const result = stmt.run(id);
  return result.changes > 0;
}

export function searchPersons(query: string): Person[] {
  const database = getDatabase();
  const stmt = database.prepare(`
    SELECT * FROM persons 
    WHERE name LIKE ? OR birthplace LIKE ? OR deathplace LIKE ? OR notes LIKE ?
    ORDER BY name
  `);
  const searchPattern = `%${query}%`;
  return stmt.all(searchPattern, searchPattern, searchPattern, searchPattern) as Person[];
}

// Relationship operations
export function addParentChild(childId: number, parentId: number): Relationship {
  const database = getDatabase();
  const stmt = database.prepare(`
    INSERT INTO relationships (person_id, related_person_id, relationship_type)
    VALUES (?, ?, 'parent')
  `);

  const result = stmt.run(childId, parentId);
  return getRelationship(result.lastInsertRowid as number)!;
}

export function addSpouse(
  personId: number,
  spouseId: number,
  anniversary?: string
): Relationship[] {
  const database = getDatabase();

  // Add bidirectional spouse relationship
  const stmt = database.prepare(`
    INSERT INTO relationships (person_id, related_person_id, relationship_type, anniversary)
    VALUES (?, ?, 'spouse', ?)
  `);

  const result1 = stmt.run(personId, spouseId, anniversary || null);
  const result2 = stmt.run(spouseId, personId, anniversary || null);

  return [
    getRelationship(result1.lastInsertRowid as number)!,
    getRelationship(result2.lastInsertRowid as number)!,
  ];
}

export function getRelationship(id: number): Relationship | undefined {
  const database = getDatabase();
  const stmt = database.prepare('SELECT * FROM relationships WHERE id = ?');
  return stmt.get(id) as Relationship | undefined;
}

export function getParents(personId: number): Person[] {
  const database = getDatabase();
  const stmt = database.prepare(`
    SELECT p.* FROM persons p
    JOIN relationships r ON p.id = r.related_person_id
    WHERE r.person_id = ? AND r.relationship_type = 'parent'
    ORDER BY p.name
  `);
  return stmt.all(personId) as Person[];
}

export function getChildren(personId: number): Person[] {
  const database = getDatabase();
  const stmt = database.prepare(`
    SELECT p.* FROM persons p
    JOIN relationships r ON p.id = r.person_id
    WHERE r.related_person_id = ? AND r.relationship_type = 'parent'
    ORDER BY p.birthday, p.name
  `);
  return stmt.all(personId) as Person[];
}

export function getSpouses(personId: number): SpouseInfo[] {
  const database = getDatabase();
  const stmt = database.prepare(`
    SELECT p.*, r.anniversary FROM persons p
    JOIN relationships r ON p.id = r.related_person_id
    WHERE r.person_id = ? AND r.relationship_type = 'spouse'
    ORDER BY r.anniversary, p.name
  `);
  const results = stmt.all(personId) as (Person & { anniversary: string | null })[];
  return results.map((r) => ({
    person: {
      id: r.id,
      name: r.name,
      birthday: r.birthday,
      birthplace: r.birthplace,
      deathday: r.deathday,
      deathplace: r.deathplace,
      notes: r.notes,
      created_at: r.created_at,
      updated_at: r.updated_at,
    },
    anniversary: r.anniversary,
  }));
}

export function getFamilyMember(id: number): FamilyMember | undefined {
  const person = getPerson(id);
  if (!person) return undefined;

  return {
    ...person,
    parents: getParents(id),
    children: getChildren(id),
    spouses: getSpouses(id),
  };
}

export function removeRelationship(personId: number, relatedPersonId: number, type: 'parent' | 'spouse'): boolean {
  const database = getDatabase();

  if (type === 'spouse') {
    // Remove bidirectional spouse relationship
    const stmt = database.prepare(`
      DELETE FROM relationships 
      WHERE relationship_type = 'spouse' 
      AND ((person_id = ? AND related_person_id = ?) OR (person_id = ? AND related_person_id = ?))
    `);
    const result = stmt.run(personId, relatedPersonId, relatedPersonId, personId);
    return result.changes > 0;
  } else {
    // Remove parent relationship (child -> parent)
    const stmt = database.prepare(`
      DELETE FROM relationships 
      WHERE person_id = ? AND related_person_id = ? AND relationship_type = 'parent'
    `);
    const result = stmt.run(personId, relatedPersonId);
    return result.changes > 0;
  }
}

// Bulk operations for backup/restore
export function getAllRelationships(): Relationship[] {
  const database = getDatabase();
  const stmt = database.prepare('SELECT * FROM relationships');
  return stmt.all() as Relationship[];
}

export function clearAllData(): void {
  const database = getDatabase();
  database.exec('DELETE FROM relationships');
  database.exec('DELETE FROM persons');
}

export function bulkInsertPersons(persons: Person[]): void {
  const database = getDatabase();
  const stmt = database.prepare(`
    INSERT INTO persons (id, name, birthday, birthplace, deathday, deathplace, notes, created_at, updated_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
  `);

  const insertMany = database.transaction((items: Person[]) => {
    for (const p of items) {
      stmt.run(p.id, p.name, p.birthday, p.birthplace, p.deathday, p.deathplace, p.notes, p.created_at, p.updated_at);
    }
  });

  insertMany(persons);
}

export function bulkInsertRelationships(relationships: Relationship[]): void {
  const database = getDatabase();
  const stmt = database.prepare(`
    INSERT INTO relationships (id, person_id, related_person_id, relationship_type, anniversary, created_at)
    VALUES (?, ?, ?, ?, ?, ?)
  `);

  const insertMany = database.transaction((items: Relationship[]) => {
    for (const r of items) {
      stmt.run(r.id, r.person_id, r.related_person_id, r.relationship_type, r.anniversary, r.created_at);
    }
  });

  insertMany(relationships);
}

