#!/usr/bin/env node
import { Command } from 'commander';
import chalk from 'chalk';
import Table from 'cli-table3';
import {
  initDatabase,
  addPerson,
  getPerson,
  getAllPersons,
  updatePerson,
  deletePerson,
  searchPersons,
  addParentChild,
  addSpouse,
  getFamilyMember,
  removeRelationship,
  closeDatabase,
} from './db.js';
import { createBackup, restoreBackup, listBackups } from './backup.js';
import { formatDate, formatDateForDisplay, parseDate } from './utils.js';

const program = new Command();

program
  .name('vamsa')
  .description('A command-line family tree management tool')
  .version('0.1.0');

// Initialize database before any command
program.hook('preAction', () => {
  initDatabase();
});

// Cleanup on exit
program.hook('postAction', () => {
  closeDatabase();
});

// Add a person
program
  .command('add <name>')
  .description('Add a new family member')
  .option('-b, --birthday <date>', 'Birthday (YYYY-MM-DD)')
  .option('-p, --birthplace <place>', 'Birthplace')
  .option('-d, --deathday <date>', 'Date of death (YYYY-MM-DD)')
  .option('--deathplace <place>', 'Place of death')
  .option('-n, --notes <notes>', 'Additional notes')
  .action((name, options) => {
    try {
      // Parse and validate dates
      const birthday = options.birthday ? formatDate(parseDate(options.birthday)) : undefined;
      const deathday = options.deathday ? formatDate(parseDate(options.deathday)) : undefined;

      const person = addPerson(name, {
        birthday,
        birthplace: options.birthplace,
        deathday,
        deathplace: options.deathplace,
        notes: options.notes,
      });
      console.log(chalk.green(`Added ${person.name} with ID ${person.id}`));
    } catch (error) {
      console.error(chalk.red(`Error: ${(error as Error).message}`));
      process.exit(1);
    }
  });

// List all persons
program
  .command('list')
  .description('List all family members')
  .action(() => {
    const persons = getAllPersons();
    if (persons.length === 0) {
      console.log(chalk.yellow('No family members found.'));
      return;
    }

    const table = new Table({
      head: ['ID', 'Name', 'Birthday', 'Birthplace'],
      style: { head: ['cyan'] },
    });

    for (const p of persons) {
      table.push([p.id, p.name, formatDateForDisplay(p.birthday), p.birthplace || '-']);
    }

    console.log(table.toString());
  });

// Show person details
program
  .command('show <id>')
  .description('Show details of a family member')
  .action((id) => {
    const member = getFamilyMember(parseInt(id, 10));
    if (!member) {
      console.log(chalk.red(`Person with ID ${id} not found.`));
      return;
    }

    console.log(chalk.bold.cyan(`\n${member.name}`));
    console.log('─'.repeat(40));

    if (member.birthday) console.log(`Birthday: ${formatDateForDisplay(member.birthday)}`);
    if (member.birthplace) console.log(`Birthplace: ${member.birthplace}`);
    if (member.deathday) console.log(`Died: ${formatDateForDisplay(member.deathday)}`);
    if (member.deathplace) console.log(`Place of death: ${member.deathplace}`);
    if (member.notes) console.log(`Notes: ${member.notes}`);

    if (member.parents.length > 0) {
      console.log(chalk.bold('\nParents:'));
      for (const parent of member.parents) {
        console.log(`  - ${parent.name} (ID: ${parent.id})`);
      }
    }

    if (member.spouses.length > 0) {
      console.log(chalk.bold('\nSpouses:'));
      for (const spouse of member.spouses) {
        const anniversary = spouse.anniversary
          ? ` (married: ${formatDateForDisplay(spouse.anniversary)})`
          : '';
        console.log(`  - ${spouse.person.name} (ID: ${spouse.person.id})${anniversary}`);
      }
    }

    if (member.children.length > 0) {
      console.log(chalk.bold('\nChildren:'));
      for (const child of member.children) {
        console.log(`  - ${child.name} (ID: ${child.id})`);
      }
    }

    console.log();
  });

// Update person
program
  .command('update <id>')
  .description('Update a family member')
  .option('-N, --name <name>', 'New name')
  .option('-b, --birthday <date>', 'Birthday (YYYY-MM-DD)')
  .option('-p, --birthplace <place>', 'Birthplace')
  .option('-d, --deathday <date>', 'Date of death (YYYY-MM-DD)')
  .option('--deathplace <place>', 'Place of death')
  .option('-n, --notes <notes>', 'Additional notes')
  .option('--clear-birthday', 'Clear birthday')
  .option('--clear-deathday', 'Clear death date')
  .action((id, options) => {
    try {
      const updates: Record<string, string | null | undefined> = {};

      if (options.name) updates.name = options.name;
      if (options.birthday) updates.birthday = formatDate(parseDate(options.birthday));
      if (options.birthplace) updates.birthplace = options.birthplace;
      if (options.deathday) updates.deathday = formatDate(parseDate(options.deathday));
      if (options.deathplace) updates.deathplace = options.deathplace;
      if (options.notes) updates.notes = options.notes;
      if (options.clearBirthday) updates.birthday = null;
      if (options.clearDeathday) updates.deathday = null;

      const person = updatePerson(parseInt(id, 10), updates);
      if (!person) {
        console.log(chalk.red(`Person with ID ${id} not found.`));
        return;
      }

      console.log(chalk.green(`Updated ${person.name}`));
    } catch (error) {
      console.error(chalk.red(`Error: ${(error as Error).message}`));
      process.exit(1);
    }
  });

// Delete person
program
  .command('delete <id>')
  .description('Delete a family member')
  .action((id) => {
    const person = getPerson(parseInt(id, 10));
    if (!person) {
      console.log(chalk.red(`Person with ID ${id} not found.`));
      return;
    }

    const deleted = deletePerson(parseInt(id, 10));
    if (deleted) {
      console.log(chalk.green(`Deleted ${person.name}`));
    }
  });

// Search persons
program
  .command('search <query>')
  .description('Search family members')
  .action((query) => {
    const results = searchPersons(query);
    if (results.length === 0) {
      console.log(chalk.yellow('No matches found.'));
      return;
    }

    const table = new Table({
      head: ['ID', 'Name', 'Birthday', 'Birthplace'],
      style: { head: ['cyan'] },
    });

    for (const p of results) {
      table.push([p.id, p.name, formatDateForDisplay(p.birthday), p.birthplace || '-']);
    }

    console.log(table.toString());
  });

// Add parent relationship
program
  .command('add-parent <child-id> <parent-id>')
