import { format, parse, isValid } from 'date-fns';

/**
 * Parse a date string in various formats and return a Date object
 * @param dateStr - Date string to parse (supports YYYY-MM-DD, MM/DD/YYYY, etc.)
 * @returns Parsed Date object
 * @throws Error if date string is invalid
 */
export function parseDate(dateStr: string): Date {
  // Try ISO format first (YYYY-MM-DD)
  let date = parse(dateStr, 'yyyy-MM-dd', new Date());
  if (isValid(date)) return date;

  // Try US format (MM/DD/YYYY)
  date = parse(dateStr, 'MM/dd/yyyy', new Date());
  if (isValid(date)) return date;

  // Try European format (DD/MM/YYYY)
  date = parse(dateStr, 'dd/MM/yyyy', new Date());
  if (isValid(date)) return date;

  throw new Error(`Invalid date format: ${dateStr}. Use YYYY-MM-DD format.`);
}

/**
 * Format a Date object to YYYY-MM-DD string for storage
 * @param date - Date object to format
 * @returns Formatted date string
 */
export function formatDate(date: Date): string {
  return format(date, 'yyyy-MM-dd');
}

/**
 * Format a date string for display (e.g., "January 15, 1950")
 * @param dateStr - Date string in YYYY-MM-DD format, or null
 * @returns Formatted date string for display, or '-' if null
 */
export function formatDateForDisplay(dateStr: string | null): string {
  if (!dateStr) return '-';

  // Parse the stored YYYY-MM-DD format
  // Note: We parse with UTC to avoid timezone issues since we're storing dates only
  const [year, month, day] = dateStr.split('-').map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));

  return format(date, 'MMMM d, yyyy');
}

/**
 * Calculate age from birthday to optional end date (or today)
 * @param birthday - Birthday in YYYY-MM-DD format
 * @param endDate - Optional end date in YYYY-MM-DD format (defaults to today)
 * @returns Age in years
 */
export function calculateAge(birthday: string, endDate?: string): number {
  const [birthYear, birthMonth, birthDay] = birthday.split('-').map(Number);

  let endYear: number, endMonth: number, endDay: number;
  if (endDate) {
    [endYear, endMonth, endDay] = endDate.split('-').map(Number);
  } else {
    const today = new Date();
    endYear = today.getFullYear();
    endMonth = today.getMonth() + 1;
    endDay = today.getDate();
  }

  let age = endYear - birthYear;

  // Adjust if birthday hasn't occurred yet this year
  if (endMonth < birthMonth || (endMonth === birthMonth && endDay < birthDay)) {
    age--;
  }

  return age;
}

