import { existsSync, mkdirSync, writeFileSync, readFileSync, readdirSync } from 'fs';
import { join } from 'path';
import {
  getDataDir,
  getAllPersons,
  getAllRelationships,
  clearAllData,
  bulkInsertPersons,
  bulkInsertRelationships,
} from './db.js';
import type { BackupData, BackupMetadata } from './types.js';

const BACKUP_VERSION = '1.0';

function getBackupDir(): string {
  return join(getDataDir(), 'backups');
}

export function createBackup(): string {
  const backupDir = getBackupDir();

  if (!existsSync(backupDir)) {
    mkdirSync(backupDir, { recursive: true });
  }

  const persons = getAllPersons();
  const relationships = getAllRelationships();

  const metadata: BackupMetadata = {
    version: BACKUP_VERSION,
    created_at: new Date().toISOString(),
    person_count: persons.length,
    relationship_count: relationships.length,
  };

  const backupData: BackupData = {
    metadata,
    persons,
    relationships,
  };

  const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
  const filename = `vamsa-backup-${timestamp}.json`;
  const filepath = join(backupDir, filename);

  writeFileSync(filepath, JSON.stringify(backupData, null, 2));

  return filepath;
}

export function restoreBackup(backupPath: string): void {
  // Check if it's just a filename (look in backup dir) or full path
  let fullPath = backupPath;
  if (!existsSync(backupPath)) {
    fullPath = join(getBackupDir(), backupPath);
  }

  if (!existsSync(fullPath)) {
    throw new Error(`Backup file not found: ${backupPath}`);
  }

  const content = readFileSync(fullPath, 'utf-8');
  const backupData: BackupData = JSON.parse(content);

  // Validate backup data
  if (!backupData.metadata || !backupData.persons || !backupData.relationships) {
    throw new Error('Invalid backup file format');
  }

  // Clear existing data and restore
  clearAllData();
  bulkInsertPersons(backupData.persons);
  bulkInsertRelationships(backupData.relationships);
}

export interface BackupInfo {
  filename: string;
  filepath: string;
  metadata: BackupMetadata;
}

export function listBackups(): BackupInfo[] {
  const backupDir = getBackupDir();

  if (!existsSync(backupDir)) {
    return [];
  }

  const files = readdirSync(backupDir).filter((f) => f.endsWith('.json'));
  const backups: BackupInfo[] = [];

  for (const filename of files) {
    try {
      const filepath = join(backupDir, filename);
      const content = readFileSync(filepath, 'utf-8');
      const data: BackupData = JSON.parse(content);

      if (data.metadata) {
        backups.push({
          filename,
          filepath,
          metadata: data.metadata,
        });
      }
    } catch {
      // Skip invalid backup files
    }
  }

  // Sort by creation date, newest first
  backups.sort((a, b) => b.metadata.created_at.localeCompare(a.metadata.created_at));

  return backups;
}

